fn csv<T: std::fmt::Display>(a: impl IntoIterator<Item = T>) -> String {
    a.into_iter()
        .map(|x| x.to_string())
        .collect::<Vec<_>>()
        .join(",")
}

struct ListNode {
    value: i32,
    next: Option<usize>,
}
fn arena(values: &[i32]) -> Vec<ListNode> {
    values
        .iter()
        .enumerate()
        .map(|(i, &value)| ListNode {
            value,
            next: (i + 1 < values.len()).then_some(i + 1),
        })
        .collect()
}
// Rust rejects a shared lead reference and a mutable trail reference into one
// Box chain. Two indexes into an arena can move together without that conflict.
fn remove_from_end(nodes: &mut [ListNode], head: usize, n: usize) -> Option<usize> {
    // Open a gap of n links between the two cursors, without measuring the list.
    let mut lead = Some(head);
    for _ in 0..n {
        lead = nodes[lead.expect("n is at most the list length")].next;
    }
    // Lead fell off the end during the gap, so the target is the head itself.
    let Some(mut lead) = lead else {
        return nodes[head].next;
    };
    // Move both until lead is on the last node; trail then sits before the target.
    let mut trail = head;
    while let Some(next) = nodes[lead].next {
        lead = next;
        trail = nodes[trail].next.unwrap();
    }
    let target = nodes[trail].next.unwrap();
    nodes[trail].next = nodes[target].next;
    Some(head)
}
fn remaining_values(values: &[i32], n: usize) -> Vec<i32> {
    let mut nodes = arena(values);
    let mut cursor = remove_from_end(&mut nodes, 0, n);
    let mut out = Vec::new();
    while let Some(i) = cursor {
        out.push(nodes[i].value);
        cursor = nodes[i].next;
    }
    out
}

fn main() {
    let result = csv(remaining_values(&[1, 2, 3, 4, 5], 2));
    println!("{result}");
}

